FANG={'black':'เวท','blue':'น้ำ','brown':'ผืนดิน','darkness':'ความมืด','green':'ลม'}
WOLF="สิ่งมีชีวิตที่น่ากลัวอย่างแท้จริง นี่คือ Direwolf ที่ \"วิวัฒนาการอย่างถูกต้อง\" และกลายเป็น Spiritual Lifeform แทบไม่มีกำเนิดขึ้นมาแม้สักครั้งในหนึ่งพันปี และ Direwolf กับ {x} ทั่วไปทุกตัวโค้งคำนับต่อสิ่งมีชีวิตนี้"
keys=[]
out={}
for l in open(W+rf'\tmp\d0{N}.txt',encoding='utf-8'):
    if ' = ' not in l: continue
    k,v=l.rstrip('\n').split(' = ',1)
    keys.append(k)
    vv=json.loads(v)
    a=k.replace('foxablazeaqzl_wiki.wiki.','')
    m=re.fullmatch(r'mysticism\.race\.(\w+)\.description',a)
    if vv=='WIP': out[k]='WIP'; continue
    mw=re.search(r'all normal Direwolves and (.+?) bow to this creature',vv)
    if mw: out[k]=WOLF.format(x=mw.group(1)); continue
    mm=re.match(r'An evolved (\w+(?: \w+)?) that has a deep connection to (?:the )?(\w+)\. It can disrupt',vv)
    if mm and m and m.group(1).startswith('mystical_'):
        el={'magic':'เวท','water':'น้ำ','earth':'ผืนดิน','dark':'ความมืด','wind':'ลม'}[mm.group(2)]
        out[k]=f"{mm.group(1)} ที่วิวัฒนาการแล้วและมีความเชื่อมโยงลึกซึ้งกับ{el} "+DIS; continue
    if m and m.group(1) in D: out[k]=D[m.group(1)]; continue
    m2=re.fullmatch(r'mysticism\.skill\.(\w+)\.description',a)
    if m2 and m2.group(1) in S: out[k]=S[m2.group(1)]
print('keys',len(keys),'out',len(out),[k.split('wiki.')[-1] for k in keys if k not in out])
json.dump(out,open(W+rf'\tmp\t0{N}.json','w',encoding='utf-8'),ensure_ascii=False)
